      "arFull": "اَلْحَمْدُ لِلّٰهِ فَاطِرِ السَّمٰوٰتِ وَالْاَرْضِ جَاعِلِ الْمَلٰٓىِٕكَةِ رُسُلًا اُولِیْۤ اَجْنِحَةٍ مَّثْنٰی وَثُلٰثَ وَرُبٰعَ ؕ یَزِیْدُ فِی الْخَلْقِ مَا یَشَآءُ ؕ اِنَّ اللّٰهَ عَلٰی كُلِّ شَیْءٍ قَدِیْرٌ ۟",
      "ur": "اس اللہ کے لئے تمام تعریفیں سزاوار ہیں جو (ابتداءً) آسمانوں اور زمین کا پیدا کرنے واﻻ[1] اور دو دو تین تین چار چار پروں والے فرشتوں کو اپنا پیغمبر (قاصد) بنانے واﻻ ہے[2]، مخلوق میں جو چاہے زیادتی کرتا ہے[3] اللہ تعالیٰ یقیناً ہر چیز پر قادر ہے.",
      "en": "[All] praise is [due] to Allāh, Creator of the heavens and the earth, [who] made the angels messengers having wings, two or three or four. He increases in creation what He wills. Indeed, Allāh is over all things competent.",
      "footnotesUr": "[1] فَاطِرٌ کے معنی ہیں مخترع، پہلے پہل ایجاد کرنے والا، یہ اشارہ ہے اللہ کی قدرت کی طرف کہ اس نے آسمان وزمین پہلے پہل بغیر نمونے کے بنائے، تو اس کے لئے دوبارہ انسانوں کو پیدا کرنا کون سا مشکل ہے؟\n[2] مراد جبرائیل، میکائیل، اسرافیل اور عزرائیل فرشتے ہیں جن کو اللہ تعالیٰ انبیا کی طرف یا مختلف مہمات پر قاصد بنا کر بھیجتا ہے۔ ان میں سے کسی کے دو، کسی کے تین اور کسی کے چار پر ہیں، جن کے ذریعے سے وہ زمین پر آتے اور زمین سے آسمان پر جاتے ہیں۔\n[3] یعنی بعض فرشتوں کے اس سے بھی زیادہ پر ہیں، جیسے حدیث میں آتا ہے نبی کریم (صلى الله عليه وسلم) نے فرمایا، میں نے معراج کی رات جبرئیل (عليه السلام) کو اصلی صورت میں دیکھا، اس کے چھ سو پر تھے (صحيح بخاري، تفسير سورة النجم، باب ، فكان قاب قوسين أو أدنى) بعض نے اس کو عام رکھا ہے، جس میں آنکھ، چہرہ، ناک اور منہ ہر چیز کا حسن داخل ہے۔",
