      "arFull": "اَلَّذِیْنَ كَفَرُوْا لَهُمْ عَذَابٌ شَدِیْدٌ ؕ۬ وَالَّذِیْنَ اٰمَنُوْا وَعَمِلُوا الصّٰلِحٰتِ لَهُمْ مَّغْفِرَةٌ وَّاَجْرٌ كَبِیْرٌ ۟۠",
