      "footnotesUr": "[1] یہ بھی اس کی شان بےنیازی ہی کی ایک مثال ہے کہ اگر وہ چاہے تو تمہیں فنا کے گھاٹ اتار کے تمہاری جگہ ایک نئی مخلوق پیدا کردے، جو اس کی اطاعت گزار ہو، اس کی نافرمان نہیں یا یہ مطلب ہے کہ ایک نئی مخلوق اور نیا عالم پیدا کردے جس سے تم ناآشنا ہو۔",
